-- Public account registration requests membership; it does not grant membership on signup.
create table if not exists public.access_requests (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, requested_role public.app_role not null check(requested_role in ('customer','supplier','driver')), full_name text not null check(length(trim(full_name)) between 2 and 160), organization_name text, phone text, notes text, status text not null default 'pending' check(status in ('pending','approved','rejected')), reviewed_by uuid references auth.users(id), reviewed_at timestamptz, created_at timestamptz not null default now());
create index if not exists access_requests_company_status_created_idx on public.access_requests(company_id,status,created_at desc);
create unique index if not exists access_requests_one_pending_per_user_company_idx on public.access_requests(company_id,user_id) where status='pending';
alter table public.access_requests enable row level security; revoke all on public.access_requests from public,anon; grant select on public.access_requests to authenticated;
create policy access_requests_read_own_or_manager on public.access_requests for select to authenticated using(user_id=(select auth.uid()) or public.is_company_manager(company_id));
create or replace function public.submit_access_request(_role public.app_role,_full_name text,_organization_name text default null,_phone text default null,_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare actor uuid:=auth.uid(); target_company uuid; request_id uuid; company_count integer; begin if actor is null then raise exception 'برای ثبت درخواست ابتدا وارد حساب شوید'; end if; if _role not in ('customer'::public.app_role,'supplier'::public.app_role,'driver'::public.app_role) then raise exception 'این نقش از مسیر درخواست عمومی قابل دریافت نیست'; end if; if length(trim(coalesce(_full_name,'')))<2 or length(trim(_full_name))>160 then raise exception 'نام باید بین ۲ تا ۱۶۰ نویسه باشد'; end if; if exists(select 1 from public.memberships m where m.user_id=actor and m.active) then raise exception 'این حساب از قبل عضویت فعال دارد'; end if; select count(*) into company_count from public.companies; if company_count<>1 then raise exception 'مجموعه مقصد باید از طریق راه‌اندازی مدیر مشخص شود'; end if; select c.id into target_company from public.companies c limit 1; if exists(select 1 from public.access_requests r where r.company_id=target_company and r.user_id=actor and r.status='pending') then raise exception 'درخواست بررسی‌نشده‌ای برای این حساب وجود دارد'; end if; insert into public.access_requests(company_id,user_id,requested_role,full_name,organization_name,phone,notes) values(target_company,actor,_role,trim(_full_name),nullif(trim(coalesce(_organization_name,'')),''),nullif(trim(coalesce(_phone,'')),''),nullif(trim(coalesce(_notes,'')),'')) returning id into request_id; return request_id; end $$;
revoke all on function public.submit_access_request(public.app_role,text,text,text,text) from public,anon; grant execute on function public.submit_access_request(public.app_role,text,text,text,text) to authenticated;
create or replace function public.review_access_request(_request uuid,_decision text) returns uuid language plpgsql security definer set search_path='' as $$ declare actor uuid:=auth.uid(); req public.access_requests%rowtype; new_customer uuid; new_supplier uuid; begin if actor is null then raise exception 'ورود الزامی است'; end if; if _decision not in ('approved','rejected') then raise exception 'تصمیم نامعتبر است'; end if; select * into req from public.access_requests r where r.id=_request for update; if not found then raise exception 'درخواست پیدا نشد'; end if; if not public.is_company_manager(req.company_id) then raise exception 'فقط مدیر مجاز می‌تواند درخواست را بررسی کند'; end if; if req.status<>'pending' then raise exception 'این درخواست قبلاً بررسی شده است'; end if; if exists(select 1 from public.memberships m where m.company_id=req.company_id and m.user_id=req.user_id and m.active) then raise exception 'این حساب در حال حاضر عضویت فعال دارد'; end if; if _decision='rejected' then update public.access_requests set status='rejected',reviewed_by=actor,reviewed_at=now() where id=req.id; return req.id; end if; if req.requested_role='customer' then insert into public.customers(company_id,name,phone,active) values(req.company_id,req.organization_name,req.phone,true) returning id into new_customer; elsif req.requested_role='supplier' then insert into public.suppliers(company_id,name,phone,active) values(req.company_id,coalesce(req.organization_name,req.full_name),req.phone,true) returning id into new_supplier; end if; insert into public.memberships(company_id,user_id,role,customer_id,supplier_id,created_by) values(req.company_id,req.user_id,req.requested_role,new_customer,new_supplier,actor); update public.access_requests set status='approved',reviewed_by=actor,reviewed_at=now() where id=req.id; return req.id; end $$;
revoke all on function public.review_access_request(uuid,text) from public,anon; grant execute on function public.review_access_request(uuid,text) to authenticated;
